const express = require('express');
const router = express.Router();
const multer = require('multer');
const Product = require('../models/Product'); // Ensures correct Mongoose model path

// Multer storage setup for image uploads
const storage = multer.diskStorage({
  destination: (req, file, cb) => cb(null, 'uploads/'),
  filename: (req, file, cb) => cb(null, Date.now() + '-' + file.originalname)
});
const upload = multer({ storage });

// 1. POST route: Matches http://localhost:4000/api/seller/products called in AddProductPage.jsx
router.post('/products', upload.array('images', 10), async (req, res) => {
  try {
    const imagePaths = req.files ? req.files.map(file => `/uploads/${file.filename}`) : [];

    const newProduct = new Product({
      title: req.body.title,
      brand: req.body.brand,
      category: req.body.category,
      price: Number(req.body.price),
      mrp: Number(req.body.mrp),
      stock: Number(req.body.stock),
      description: req.body.description,
      features: req.body.features,
      images: imagePaths,
      imageUrl: imagePaths[0] || '' // Main image fallback
    });

    const savedProduct = await newProduct.save();
    res.status(201).json(savedProduct);
  } catch (error) {
    console.error('Error saving product:', error);
    res.status(500).json({ message: 'Error adding product', error: error.message });
  }
});

// 2. GET route: To fetch all products for the Products page
router.get('/products', async (req, res) => {
  try {
    const products = await Product.find().sort({ createdAt: -1 });
    res.status(200).json(products);
  } catch (error) {
    res.status(500).json({ message: 'Error fetching products', error: error.message });
  }
});

module.exports = router;
